.chip.completed { background: rgba(52, 193, 119, 0.15); color: var(--green); }
.chip.failed { background: rgba(229, 72, 77, 0.15); color: var(--red); }
.run-row .meta { color: var(--text-faint); font-size: 11.5px; white-space: nowrap; }

@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
.pulsing { animation: pulse 1.4s ease-in-out infinite; }

